<script lang="ts">
 import {languageOverrides} from "./localization";import type {Project} from './model';import {translator} from './i18n';import {displayPeriod} from './date-format';import {CalendarDays,ReceiptText,Wallet,TriangleAlert,Gauge,Calculator,ChartNoAxesCombined,Save,FolderOpen,Archive,BookOpen} from "./icons";export let project:Project;export let charges:string;export let paid:string;export let balance:string;export let attention:number;export let oncommand:(id:string)=>void;$:t=translator(project.settings.language,$languageOverrides);const actions=[{id:'individual-readings',ru:'Индивидуальные показания',ro:'Indexuri individuale',en:'Individual readings',icon:Gauge},{id:'shared-meters',ru:'Общие счётчики',ro:'Contoare comune',en:'Shared meters',icon:Gauge},{id:'batch-charges',ru:'Начислить услуги',ro:'Calculează serviciile',en:'Calculate charges',icon:Calculator},{id:'payment-batches',ru:'Внести оплаты',ro:'Înregistrează plățile',en:'Record payments',icon:Wallet},{id:'receipts',ru:'Подготовить квитанции',ro:'Pregătește facturile',en:'Prepare receipts',icon:ReceiptText},{id:'reports',ru:'Проверить ведомость',ro:'Verifică balanța',en:'Review account balances',icon:ChartNoAxesCombined}];</script>
<div class="overview-current"><header><button class="button secondary" onclick={()=>oncommand('period')}><CalendarDays size={18}/>{displayPeriod(project.settings.period,project)}</button>{#if project.demo}<span class="demo-note">{t('Демонстрационная база · вымышленные данные','Bază demonstrativă · date fictive','Demo database · fictional data')}</span>{/if}</header><section class="overview-metrics"><article><ReceiptText size={22}/><span>{t('Начислено за месяц','Calculat pentru lună','Monthly charges')}</span><strong>{charges} <small>MDL</small></strong></article><article><Wallet size={22}/><span>{t('Поступило оплат','Plăți încasate','Payments received')}</span><strong>{paid} <small>MDL</small></strong></article><article><Wallet size={22}/><span>{t('Остаток к оплате','Sold de achitat','Balance due')}</span><strong>{balance} <small>MDL</small></strong></article><article><TriangleAlert size={22}/><span>{t('Требует проверки','Necesită verificare','Needs review')}</span><strong>{attention}</strong></article></section><section class="overview-actions">{#each actions as action}<button onclick={()=>oncommand(action.id)}><action.icon size={25}/><span>{t(action.ru,action.ro,action.en)}</span></button>{/each}</section><footer><button class="button secondary" onclick={()=>oncommand('file:save')}><Save size={17}/>{t('Сохранить','Salvează')}</button><button class="button secondary" onclick={()=>oncommand('file:save-as')}><FolderOpen size={17}/>{t('Сохранить базу как…','Salvează baza ca…','Save database as…')}</button><button class="button secondary" onclick={()=>oncommand('settings')}><Archive size={17}/>{t('Параметры и резервные копии','Setări și copii de rezervă','Settings and backups')}</button><button class="button secondary" onclick={()=>oncommand('manual')}><BookOpen size={17}/>{t('Документация','Documentație')}</button></footer>{#if attention}<p class="attention-note">{t('Перед выпуском квитанций проверьте отсутствующие показания, тарифы и историю расчётов.','Înainte de emiterea facturilor verificați indexurile, tarifele și istoricul lipsă.','Before issuing receipts, review missing readings, tariffs and accounting history.')}</p>{/if}</div>
<style>.overview-current{display:grid;gap:24px;padding:16px 4px}.overview-current>header{display:flex;align-items:center;gap:18px;flex-wrap:wrap}.demo-note{font-size:12px;color:var(--muted)}.overview-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px}.overview-metrics article{display:grid;grid-template-columns:1fr auto;gap:15px;padding:20px;background:var(--hover)}.overview-metrics article :global(svg){grid-column:2;grid-row:1;color:var(--accent)}.overview-metrics span{font-size:12px;color:var(--muted)}.overview-metrics strong{grid-column:1/-1;font-size:26px;font-weight:500}.overview-metrics small{font-size:11px;color:var(--muted);font-weight:400}.overview-actions{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.overview-actions button{display:flex;align-items:center;gap:18px;padding:24px 18px;text-align:left;border:0;background:transparent;color:var(--text)}.overview-actions button:hover{background:var(--hover);outline:1px solid var(--reveal-ink,#80808030)}.overview-actions :global(svg){color:var(--accent);flex:none}footer{display:flex;gap:10px;flex-wrap:wrap}.attention-note{margin:0;line-height:1.6}</style>
